-- Drop all problematic constraints from company_data table
ALTER TABLE company_data DROP CONSTRAINT IF EXISTS company_data_company_id_key;
ALTER TABLE company_data DROP CONSTRAINT IF EXISTS company_data_file_id_key;
ALTER TABLE company_data DROP CONSTRAINT IF EXISTS company_data_company_id_file_id_key;

-- Also drop the id column if it exists (since you don't want any keys)
ALTER TABLE company_data DROP COLUMN IF EXISTS id;

-- Show the final table structure
SELECT column_name, data_type, is_nullable 
FROM information_schema.columns 
WHERE table_name = 'company_data' 
ORDER BY ordinal_position;
